import {clone,today,addMonths,parseDecimal,calculate,selectedPeriods,sumPeriods,lifetimeSummary,portfolioSummary,validateBackup} from './core.js';
import {openStore,commit,restore} from './store.js';
const BACKUP_KEY='lot-ledger-last-backup:'+new URL('.',location.href).pathname;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:n%100?2:0,minimumFractionDigits:0}).format(n/100)+' ₽';
const signedMoney=n=>(n>0?'+':'')+money(n);
const number=n=>String(n/100);const date=s=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T00:00:00Z'));
const shortDate=s=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(s+'T00:00:00Z'));
const colors=['#345c49','#a8b79a','#cfb87c','#98afb2','#b59b8e','#8e99b7','#8eae6e'];
let envelope,view='overview',mode='current',historyQuery='',periodDraft=null,installPrompt=null,busy=false;
const state=()=>envelope.state, person=id=>state().people.find(p=>p.id===id), lot=id=>state().lots.find(l=>l.id===id), computed=id=>calculate(state()).find(p=>p.id===id);
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('');
const avatar=p=>`<span class="avatar" style="--bg:${colors[(p.color||0)%colors.length]}25">${esc(initials(p.name))}</span>`;
function status(p){const d=today();return p.startDate>d?['planned','Запланирован']:p.endDate<d?['closed','Завершён']:['','В работе'];}
const badge=p=>{const [css,label]=status(p);return `<span class="badge ${css}">● ${label}</span>`;};
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function showModal(title,body,foot=''){ $('#modal-body').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close" aria-label="Закрыть">×</button></div><div class="modal-content">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){ $('#modal').close();periodDraft=null;}
function error(e){const el=$('#form-error');if(el)el.textContent=e.message||String(e);else toast(e.message||String(e));}
async function save(next,label,details=''){if(busy)return false;busy=true;try{envelope=await commit(envelope,next,label,details);render();toast('Сохранено на устройстве');return true;}catch(e){error(e);return false;}finally{busy=false;}}
function plannedStagesNotice(){
  const planned=state().periods.filter(p=>p.startDate>today()).slice().sort((a,b)=>a.startDate.localeCompare(b.startDate));
  if(!planned.length)return '';
  return `<aside class="planned-stages-notice" aria-label="Запланированные этапы"><strong>Есть запланированные этапы</strong><div class="planned-stage-dates">${planned.map(p=>`<div><b>${esc(lot(p.lotId).name)}</b><span>${date(p.startDate)} — ${date(p.endDate)}</span></div>`).join('')}</div><a class="text-button" href="#lots">Лоты и периоды ↗</a></aside>`;
}
function periodCreateActions(extra=''){
  const create=button('+ Новый период','new-period','','primary'),notice=plannedStagesNotice();
  return notice?`<div class="period-create-actions">${notice}<div class="actions">${extra}${create}</div></div>`:extra+create;
}
function pageHead(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
const button=(text,action,id='',css='')=>`<button class="btn ${css}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
function modeSwitch(label){return `<div class="segmented" role="group" aria-label="${label}"><button data-action="mode-current" class="${mode==='current'?'active':''}" aria-pressed="${mode==='current'}">Текущие</button><button data-action="mode-latest" class="${mode==='latest'?'active':''}" aria-pressed="${mode==='latest'}">С планами</button></div>`;}
function peopleTable(){
  const at=today(),current=selectedPeriods(state(),'current');
  const amounts=id=>{const s=portfolioSummary(state(),mode,at,id);return {investedKop:s.lifetime.investedKop,finalKop:s.totals.finalKop,incomeKop:s.incomeKop};};
  const total=amounts();
  const comparison=(value,base)=>mode==='latest'?`<small class="table-change">${value===base?'Без изменения':signedMoney(value-base)+' к текущим'}</small>`:'';
  const cells=(t,base)=>['investedKop','finalKop','incomeKop'].map(k=>`<td class="numeric ${k==='incomeKop'?'positive':''}">${money(t[k])}${k==='finalKop'?comparison(t.finalKop,base.finalKop):''}</td>`).join('');
  return `<div class="table-wrap"><table aria-label="Итоги вложений и процентов по людям"><thead><tr><th>Участник</th><th class="numeric">Итого<br>вложено</th><th class="numeric">Сумма<br>на конец</th><th class="numeric">Сумма<br>процентов</th></tr></thead><tbody>${state().people.map(p=>{const t=amounts(p.id);if(p.archived&&!t.finalKop&&!t.investedKop)return '';return `<tr><td><button class="person-name name-cell" data-action="person-detail" data-id="${esc(p.id)}">${avatar(p)}${esc(p.name)}</button></td>${cells(t,sumPeriods(current,p.id))}</tr>`;}).join('')}<tr class="table-total"><td>Все участники</td>${cells(total,sumPeriods(current))}</tr></tbody></table></div>`;
}
function peopleCalculation(periods){
  const all=calculate(state());
  return `<section class="panel people-calculation" aria-labelledby="people-calculation-title"><div class="section-head"><div><h2 id="people-calculation-title">Общий расчёт по людям</h2><p>${mode==='latest'?'Последние записанные этапы, включая будущие':'Последние начавшиеся этапы на '+date(today())}</p></div><div class="actions">${modeSwitch('Режим расчёта по людям')}${button('Отчёт ↗','summary-report','','small')}</div></div><div class="calculation-periods" aria-label="Этапы в расчёте">${periods.map(p=>{const stage=all.filter(x=>x.lotId===p.lotId).findIndex(x=>x.id===p.id)+1;return `<article class="calculation-period"><div><strong>${esc(lot(p.lotId).name)} · этап ${stage}</strong>${badge(p)}</div><p>${date(p.startDate)} — ${date(p.endDate)}</p>${mode==='latest'?`<small>${p.startDate>today()?'Используется будущий записанный этап':'Следующий этап не записан — сумма остаётся прежней'}</small>`:''}</article>`;}).join('')||'<p class="help-text">Выбранных этапов пока нет.</p>'}</div><p class="calculation-help">Итого вложено — начальные суммы и все пополнения участника за историю. Сумма на конец — итог выбранных выше этапов каждого лота. Сумма процентов — разница этих сумм.</p>${peopleTable()}<p class="calculation-formula">Сумма процентов = сумма на конец − итого вложено. Проценты текущих и будущих этапов рассчитаны на их окончание.</p></section>`;
}
function periodTable(p){return `<div class="table-wrap"><table><thead><tr><th>Участник</th><th class="numeric">Ставка</th><th class="numeric">Накоплено</th><th class="numeric">Добавлено</th><th class="numeric">Выведено</th><th class="numeric">Итого</th><th class="numeric">На конец</th></tr></thead><tbody>${p.rows.map(r=>`<tr><td class="name-cell">${avatar(person(r.personId))}${esc(person(r.personId).name)}</td><td class="numeric">${number(r.rateBps)}%</td>${['accumulatedKop','addedKop','withdrawnKop','principalKop','finalKop'].map(k=>`<td class="numeric">${money(r[k])}</td>`).join('')}</tr>`).join('')}<tr class="table-total"><td>Итого</td><td></td>${['accumulatedKop','addedKop','withdrawnKop','principalKop','finalKop'].map(k=>`<td class="numeric">${money(p.totals[k])}</td>`).join('')}</tr></tbody></table></div>`;}
function lotCard(p){const progress=Math.max(0,Math.min(100,(Date.parse(today())-Date.parse(p.startDate))/(Date.parse(p.endDate)-Date.parse(p.startDate))*100));const days=Math.ceil((Date.parse(p.endDate)-Date.parse(today()))/86400000);return `<article class="lot-card"><div class="lot-title"><h3>${esc(lot(p.lotId).name)}</h3>${badge(p)}</div><div class="lot-label">НА КОНЕЦ ПЕРИОДА</div><div class="lot-amount">${money(p.totals.finalKop)}</div><div class="lot-date">${shortDate(p.startDate)} — ${date(p.endDate)}</div><div class="progress"><i style="width:${progress}%"></i></div><div class="lot-foot"><span>${days<0?'Период завершён':p.startDate>today()?'Начало '+shortDate(p.startDate):days===0?'Окончание сегодня':'До окончания '+days+' дн.'}</span><span class="positive">${signedMoney(p.totals.profitKop)}</span></div><div class="actions">${button('Подробнее ↗','period-detail',p.id,'small')}${button('Изменить','edit-period',p.id,'small')}</div></article>`;}
function historyItem(h){const at=new Date(h.at);return `<div class="timeline-item"><span class="timeline-icon">↗</span><div class="timeline-copy"><strong>${esc(h.label)}</strong><p>${esc(h.details||'Изменение сохранено в журнале')}</p><button class="text-button" data-action="history-detail" data-id="${esc(h.id)}">Посмотреть изменение</button></div><time class="timeline-time">${at.toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short',year:'numeric'})}<br>${at.toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'})}</time></div>`;}
function incomeByMonth(summary){const monthLabel=m=>new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01T00:00:00Z'));return `<section class="panel" style="margin-bottom:23px"><div class="section-head"><div><h2>Проценты по месяцам</h2><p>Только процентные начисления по лотам, по месяцу окончания периода.</p></div><span class="badge ${mode==='latest'?'planned':'closed'}">${mode==='latest'?'С учётом планов':'Завершённые периоды'}</span></div><div class="table-wrap"><table><thead><tr><th>Месяц</th><th class="numeric">Проценты</th>${mode==='latest'?'<th class="numeric">Ожидается</th>':''}</tr></thead><tbody>${summary.months.map(m=>`<tr><td>${esc(monthLabel(m.month))}</td><td class="numeric positive">${money(m.earnedKop)}</td>${mode==='latest'?`<td class="numeric">${money(m.expectedKop)}</td>`:''}</tr>`).join('')||`<tr><td colspan="3">Завершённых периодов пока нет.</td></tr>`}<tr class="table-total"><td>За все месяцы</td><td class="numeric">${money(summary.earnedProfitKop)}</td>${mode==='latest'?`<td class="numeric">${money(summary.expectedProfitKop)}</td>`:''}</tr></tbody></table></div></section>`;}
function metricDetail(){const {totals,lifetime,incomeKop}=portfolioSummary(state(),mode);showModal('Как считается доход на конец',`<p>Из конечной суммы выбранных лотов вычитаем начальные суммы и все новые пополнения за историю.</p><div class="preview-total"><span>Сумма на конец<b>${money(totals.finalKop)}</b></span><span>Минус всего вложено<b>${money(lifetime.investedKop)}</b></span><span>Доход на конец<b>${money(incomeKop)}</b></span></div><p><b>${money(totals.finalKop)} − ${money(lifetime.investedKop)} = ${money(incomeKop)}</b></p><p>«Итого вложено» = начальные суммы ${money(lifetime.openingKop)} + новые пополнения ${money(lifetime.addedKop)} = ${money(lifetime.investedKop)}. Начальная сумма каждого лота учитывается один раз. Переносы между этапами повторно не прибавляются. Таблица «Проценты по месяцам» показывает процентные начисления по месяцу окончания этапа.</p>`,button('Понятно','close'));}
function overview(){const {periods,totals:t,lifetime,incomeKop}=portfolioSummary(state(),mode),people=state().people.filter(p=>!p.archived||sumPeriods(periods,p.id).principalKop);let stop=0;const parts=people.map((p,i)=>{const start=stop;stop+=t.principalKop?sumPeriods(periods,p.id).principalKop/t.principalKop*100:0;return `${colors[(p.color||i)%colors.length]} ${start}% ${stop}%`;});
return pageHead('Всё под контролем','Люди, вложения и результаты — в одном месте',periodCreateActions())+
`<div class="section-head"><div class="eyebrow" style="margin:0">${mode==='current'?'СВОДКА ПО ПОСЛЕДНИМ НАЧАВШИМСЯ ЭТАПАМ':'СВОДКА С УЧЁТОМ ЗАПИСАННЫХ ПЛАНОВ'}</div>${modeSwitch('Периоды в сводке')}</div>
<div class="stats"><article class="stat dark"><div class="stat-label">Итого вложено <span>↗</span></div><div class="stat-value">${money(lifetime.investedKop).replace(' ₽','<small>₽</small>')}</div><div class="stat-sub">Начальные суммы + пополнения${mode==='latest'?' · включая планы':' · без будущих'}</div></article><article class="stat"><div class="stat-label">Сумма на конец <span>◈</span></div><div class="stat-value">${money(t.finalKop).replace(' ₽','<small>₽</small>')}</div><div class="stat-sub">Расчёт по выбранным периодам</div></article><article class="stat"><div class="stat-label">Доход на конец <span>↗</span></div><div class="stat-value positive">${signedMoney(incomeKop).replace(' ₽','<small>₽</small>')}</div><div class="stat-sub">Сумма на конец − Итого вложено</div><button class="text-button stat-help" data-action="metric-detail" data-id="income" aria-label="Как считается доход">Как считается</button></article></div>
<div class="overview-grid"><section class="panel"><div class="section-head"><div><h2>Ваши лоты</h2><p>Последний выбранный период каждого лота</p></div><a class="text-button" href="#lots">Все периоды ↗</a></div><div class="lots-grid">${periods.map(lotCard).join('')||'<div class="empty">Начавшихся периодов пока нет.<br>Выберите «С планами» или создайте период.</div>'}</div></section><section class="panel"><h2>Кто участвует</h2><div class="allocation-layout"><div class="distribution"><div class="donut" style="--ring:conic-gradient(${t.principalKop?parts.join(','):'#e7ecdf 0% 100%'})"><div class="donut-label">${people.length}<small>участника</small></div></div></div><div class="legend">${people.map(p=>{const v=sumPeriods(periods,p.id).principalKop;return `<div class="legend-row"><i style="background:${colors[(p.color||0)%colors.length]}"></i><span>${esc(p.name)}</span><strong>${t.principalKop?(v/t.principalKop*100).toFixed(1).replace('.',','):0}%</strong></div>`;}).join('')}<a href="#people" class="text-button">Управление людьми ↗</a></div></div></section></div>
${peopleCalculation(periods)}
<div class="note-strip"><span>ⓘ</span><span>${mode==='current'?'«Текущие» — последние начавшиеся периоды на '+date(today())+' Завершённый период остаётся в сводке до начала следующего.':'«С планами» — последние периоды, включая будущие. Их суммы — план, а не текущий остаток.'} «Итого вложено» — начальные суммы каждого лота плюс новые пополнения за всю историю. Начальные суммы учтены один раз, переносы повторно не прибавляются. Доход на конец = сумма на конец − Итого вложено.</span></div>
${incomeByMonth(lifetime)}
${envelope.history.length?`<section class="panel"><div class="section-head"><h2>Последние изменения</h2><a class="text-button" href="#history">Вся история ↗</a></div><div class="timeline">${envelope.history.slice(-3).reverse().map(historyItem).join('')}</div></section>`:''}`;}
function peoplePage(){const at=today();return pageHead('Люди','Все вложения и результат каждого участника',modeSwitch('Режим расчёта участников')+button('+ Добавить человека','new-person','','primary'))+`<div class="people-grid">${state().people.map(p=>{const s=portfolioSummary(state(),mode,at,p.id),current=portfolioSummary(state(),'current',at,p.id),difference=s.totals.finalKop-current.totals.finalKop,future=s.periods.some(x=>x.startDate>at&&x.rows.some(r=>r.personId===p.id&&(r.accumulatedKop||r.addedKop||r.withdrawnKop)));return `<article class="panel person-card ${p.archived?'archived':''}">${avatar(p)}${p.archived?'<span class="badge closed" style="float:right">В архиве</span>':''}<h3>${esc(p.name)}</h3><p>${mode==='latest'?'С учётом записанных планов':'По последним начавшимся этапам'}</p><dl class="person-totals"><div><dt>Итого вложено</dt><dd>${money(s.lifetime.investedKop)}</dd></div><div><dt>Сумма на конец</dt><dd>${money(s.totals.finalKop)}</dd></div><div><dt>Сумма процентов</dt><dd class="positive">${money(s.incomeKop)}</dd></div></dl>${mode==='latest'?`<p class="person-plan-note">${future?(difference?signedMoney(difference)+' к текущей сумме на конец':'Сумма на конец без изменения'):'Будущий этап участника не записан. Все его вложения и проценты учтены.'}</p>`:''}${p.note?`<p>${esc(p.note)}</p>`:''}<div class="actions">${button('Расчёты','person-detail',p.id,'small')}${button('Изменить','edit-person',p.id,'small')}${button(p.archived?'Вернуть':'В архив','archive-person',p.id,'small')}</div></article>`;}).join('')||'<div class="empty">Добавьте первого участника.</div>'}</div><div class="note-strip">ⓘ Итого вложено = начальные суммы + все пополнения участника. Сумма процентов = сумма на конец − итого вложено. Проценты выбранных этапов рассчитаны на их окончание. Участники из архива сохраняются в расчётах и истории.</div>`;}

function lotsPage(){const all=calculate(state());return pageHead('Лоты и периоды','История каждого лота, от первого вложения до нового периода',periodCreateActions(button('+ Добавить лот','new-lot')))+state().lots.map(l=>{const periods=all.filter(p=>p.lotId===l.id);return `<section class="panel lot-section"><div class="section-head"><div><h2>${esc(l.name)}</h2><p>${periods.length} периода · Все участники учтены</p></div><div class="actions">${button('Переименовать','rename-lot',l.id,'small')}${button('+ Следующий период','next-period',l.id,'small primary')}</div></div>${periods.length?periods.slice().reverse().map((p,i)=>`<article class="period-line"><div class="period-summary"><div class="period-main"><span class="period-number">${periods.length-i}</span><div><h3>${date(p.startDate)} — ${date(p.endDate)}</h3><small>Итого ${money(p.totals.principalKop)} · Доход ${signedMoney(p.totals.profitKop)}</small></div></div><span class="period-amount">${money(p.totals.finalKop)}</span>${badge(p)}<div class="actions">${button('Изменить','edit-period',p.id,'small')}${button('Отчёт','period-report',p.id,'small')}</div></div><details><summary>Расчёт по людям</summary>${periodTable(p)}${p.note?`<p class="help-text">${esc(p.note)}</p>`:''}</details></article>`).join(''):'<div class="empty">Периодов пока нет. Создайте первый.</div>'}</section>`;}).join('');}
function historyPage(){const items=envelope.history.filter(h=>(h.label+' '+h.details).toLocaleLowerCase('ru').includes(historyQuery.toLocaleLowerCase('ru'))).slice().reverse();return pageHead('История','Все изменения сохранены: можно посмотреть и восстановить прежнее состояние',button('Резервная копия ↓','export'))+`<div class="history-tools"><input class="search" id="history-search" placeholder="Поиск по истории…" aria-label="Поиск по истории" value="${esc(historyQuery)}"><span class="badge closed">${envelope.history.length} изменений</span></div><section class="panel"><div id="history-items">${items.length?items.map(historyItem).join(''):'<div class="empty">'+(envelope.history.length?'Ничего не найдено.':'Изменений пока нет.<br>Добавьте людей и лоты или восстановите JSON-копию в разделе «Мои данные».')+'</div>'}</div></section>`;}
function dataPage(){return pageHead('Мои данные','Ваши расчёты хранятся отдельно, в формате приложения')+`<div class="data-grid"><section class="panel data-card"><span class="data-symbol">↓</span><h2>Резервная копия</h2><p>Все люди, лоты, периоды и журнал изменений в одном JSON-файле. Сохраните копию, чтобы перенести данные на другое устройство или восстановить их.</p>${button('Скачать JSON-копию','export','','primary')}<p id="backup-at">${localStorage.getItem(BACKUP_KEY)?'Последняя выгрузка: '+esc(new Date(localStorage.getItem(BACKUP_KEY)).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})):'Резервная копия ещё не выгружалась.'}</p></section><section class="panel data-card"><span class="data-symbol">↑</span><h2>Восстановление</h2><p>Выберите резервную копию этого приложения. Перед заменой увидите количество записей. Текущее состояние сохранится в истории восстановления.</p>${button('Выбрать JSON-файл','import')}<input type="file" accept=".json,application/json" id="import-file" class="file-input"></section><section class="panel data-card"><span class="data-symbol">▣</span><h2>Установить на устройство</h2><p>Приложение работает без интернета после первого открытия. На iPhone: Safari → «Поделиться» → «На экран Домой». В Chrome или Edge: пункт установки приложения в меню браузера.</p>${button('Установить / инструкция','install')}</section><section class="panel data-card"><span class="data-symbol">◈</span><h2>Как считаются суммы</h2><p>Итого = накоплено + добавлено − выведено.<br>На конец = округлить вниз(итого × (1 + ставка / 100)). Округление до целого рубля выполняется по каждому человеку; затем суммы складываются.</p><p>Итого вложено = начальные суммы каждого лота + новые пополнения за историю. Начальные суммы учитываются один раз, переносы между этапами повторно не добавляются.<br>Доход на конец в сводке = сумма на конец выбранных лотов − Итого вложено.</p><p>Ставка относится ко всему периоду. По умолчанию — 8% и два календарных месяца. Итог предыдущего периода переносится в следующий.</p></section><section class="panel wide"><h2>Независимый учёт</h2><p class="help-text">В вашем учёте: ${state().people.length} участников, ${state().lots.length} лотов, ${state().periods.length} периодов. Добавляйте записи вручную или переносите их через JSON-копию. Приложение не подключается к таблицам и не изменяет исходные файлы.</p><div class="note-strip">Данные находятся в этом браузере на этом устройстве. На другом устройстве загрузите JSON-копию. Очистка данных браузера удаляет локальный учёт — сохраните резервную копию.</div></section></div>`;}
function render(){if(!envelope)return;view=location.hash.slice(1)||'overview';if(!['overview','people','lots','history','data'].includes(view))view='overview';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=({overview,people:peoplePage,lots:lotsPage,history:historyPage,data:dataPage}[view])();document.title=({overview:'Обзор',people:'Люди',lots:'Лоты и периоды',history:'История',data:'Мои данные'}[view])+' · Лоты';}
function personForm(id){const p=id?person(id):{name:'',note:''};showModal(id?'Изменить человека':'Новый участник',`<form id="person-form"><label class="field">Имя и фамилия<input name="name" required maxlength="120" value="${esc(p.name)}" placeholder="Например, Иван Петров" autocomplete="off"></label><br><label class="field">Заметка (необязательно)<textarea name="note" maxlength="1000" placeholder="Что важно помнить">${esc(p.note)}</textarea></label><div class="error" id="form-error"></div></form>`,button('Отмена','close')+`<button class="btn primary" type="submit" form="person-form">${id?'Сохранить':'Добавить участника'}</button>`);$('#person-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),note=f.get('note').trim();if(!name)return error(new Error('Введите имя.'));const next=clone(state());if(next.people.some(x=>x.id!==id&&x.name.toLocaleLowerCase('ru')===name.toLocaleLowerCase('ru')))return error(new Error('Участник с таким именем уже есть.'));if(id)Object.assign(next.people.find(x=>x.id===id),{name,note});else next.people.push({id:crypto.randomUUID(),name,note,color:next.people.length,archived:false});if(await save(next,id?'Изменён участник':'Добавлен участник',name))close();};}
function lotForm(id){showModal(id?'Название лота':'Новый лот',`<form id="lot-form"><label class="field">Название<input name="name" required maxlength="120" value="${esc(id?lot(id).name:'')}" placeholder="Например, Лот 3"></label><div class="error" id="form-error"></div></form>`,button('Отмена','close')+'<button class="btn primary" form="lot-form">Сохранить</button>');$('#lot-form').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim(),next=clone(state());if(!name)return error(new Error('Введите название.'));if(next.lots.some(l=>l.id!==id&&l.name.toLocaleLowerCase('ru')===name.toLocaleLowerCase('ru')))return error(new Error('Лот с таким названием уже есть.'));const newId=id||crypto.randomUUID();if(id)next.lots.find(l=>l.id===id).name=name;else next.lots.push({id:newId,name});if(await save(next,id?'Переименован лот':'Добавлен лот',name)){close();if(!id)periodForm(null,newId);}};}
function dayAfter(s){const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10);}
function newDraft(lotId){const previous=calculate(state()).filter(p=>p.lotId===lotId).at(-1);const startDate=previous?dayAfter(previous.endDate):today();return {id:crypto.randomUUID(),lotId,startDate,endDate:addMonths(startDate),note:'',rows:state().people.filter(p=>!p.archived||previous?.rows.find(r=>r.personId===p.id)?.finalKop).map(p=>({personId:p.id,accumulatedKop:previous?.rows.find(r=>r.personId===p.id)?.finalKop||0,addedKop:0,withdrawnKop:0,rateBps:previous?.rows.find(r=>r.personId===p.id)?.rateBps??800,carry:!!previous}))};}
function periodForm(id,lotId){if(!state().lots.length)return lotForm();if(!state().people.length){toast('Сначала добавьте человека');return personForm();}periodDraft=id?clone(state().periods.find(p=>p.id===id)):newDraft(lotId||state().lots[0].id);drawPeriodForm(id);}
function drawPeriodForm(editId){const p=periodDraft,previous=calculate(state()).filter(x=>x.lotId===p.lotId&&x.startDate<p.startDate&&x.id!==p.id).at(-1);const active=state().people.filter(x=>!x.archived||p.rows.some(r=>r.personId===x.id));for(const person of active)if(!p.rows.some(r=>r.personId===person.id))p.rows.push({personId:person.id,accumulatedKop:0,addedKop:0,withdrawnKop:0,rateBps:800,carry:!!previous});
showModal(editId?'Изменить период':'Новый период',`<form id="period-form"><div class="form-grid"><label class="field">Лот<select id="period-lot" name="lotId" ${editId?'disabled':''}>${state().lots.map(l=>`<option value="${esc(l.id)}" ${l.id===p.lotId?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label class="field">Дата начала<input type="date" name="startDate" id="period-start" required value="${p.startDate}"></label><label class="field">Дата окончания<input type="date" name="endDate" id="period-end" required value="${p.endDate}"></label><label class="field">Ставка всем, %<div class="actions"><input style="width:75px" type="text" inputmode="decimal" id="common-rate" value="8" aria-label="Общая ставка"><button type="button" class="btn small" data-action="apply-rate">Применить</button></div></label></div><div class="table-wrap"><table class="edit-table"><thead><tr><th>Участник</th><th>Накоплено, ₽</th><th>Добавлено, ₽</th><th>Выведено, ₽</th><th>Ставка, %</th><th class="numeric">На конец</th></tr></thead><tbody>${p.rows.map(r=>{const person=state().people.find(x=>x.id===r.personId),acc=r.carry&&previous?(previous.rows.find(x=>x.personId===r.personId)?.finalKop||0):r.accumulatedKop;return `<tr data-person="${esc(r.personId)}"><td><div class="name-cell">${avatar(person)}${esc(person.name)}</div></td><td><input type="text" inputmode="decimal" data-key="accumulatedKop" aria-label="Накоплено: ${esc(person.name)}" value="${number(acc)}" ${r.carry&&previous?'disabled':''}><label class="carry-label"><input type="checkbox" data-key="carry" ${r.carry&&previous?'checked':''} ${previous?'':'disabled'}>Из прошлого периода</label></td>${['addedKop','withdrawnKop','rateBps'].map(k=>`<td><input class="${k==='rateBps'?'rate':''}" type="text" inputmode="decimal" data-key="${k}" aria-label="${k==='addedKop'?'Добавлено':k==='withdrawnKop'?'Выведено':'Ставка'}: ${esc(person.name)}" value="${number(r[k])}"></td>`).join('')}<td class="numeric row-result" data-result="${esc(r.personId)}">—</td></tr>`;}).join('')}</tbody></table></div><div class="preview-total" id="period-totals"></div><label class="field">Заметка<textarea name="note" maxlength="5000" placeholder="Например, пополнение перед новым периодом">${esc(p.note)}</textarea></label><div class="error" id="form-error"></div><p class="modal-note">Ставка действует за весь период. При изменении старых сумм следующие периоды с автопереносом пересчитываются. В истории сохранится прежнее состояние.</p></form>`,button('Отмена','close')+`<button class="btn primary" form="period-form">Сохранить период</button>`);
const form=$('#period-form');form.addEventListener('input',()=>updateDraft(editId));form.addEventListener('change',e=>{if(e.target.id==='period-lot'){periodDraft=newDraft(e.target.value);drawPeriodForm();return;}if(e.target.id==='period-start'){const v=e.target.value;if(!editId&&v)$('#period-end').value=addMonths(v);updateDraft(editId);const prev=calculate(state()).filter(x=>x.lotId===periodDraft.lotId&&x.startDate<v&&x.id!==periodDraft.id).at(-1);document.querySelectorAll('[data-person]').forEach(tr=>{const c=tr.querySelector('[data-key="carry"]');c.disabled=!prev;if(!prev)c.checked=false;});}if(e.target.dataset.key==='carry'){e.target.closest('tr').querySelector('[data-key="accumulatedKop"]').disabled=e.target.checked;}updateDraft(editId);});form.onsubmit=async e=>{e.preventDefault();try{updateDraft(editId,true);const next=clone(state());if(editId)next.periods[next.periods.findIndex(p=>p.id===editId)]=clone(periodDraft);else next.periods.push(clone(periodDraft));const name=lot(periodDraft.lotId).name,details=name+' · '+date(periodDraft.startDate)+' — '+date(periodDraft.endDate);if(await save(next,editId?'Изменён период':'Добавлен период',details))close();}catch(e){error(e);}};updateDraft(editId);}
function updateDraft(editId,throwError=false){try{const p=periodDraft,form=$('#period-form');p.startDate=form.elements.startDate.value;p.endDate=form.elements.endDate.value;p.note=form.elements.note.value.trim();for(const tr of document.querySelectorAll('[data-person]')){const r=p.rows.find(r=>r.personId===tr.dataset.person);for(const k of ['accumulatedKop','addedKop','withdrawnKop','rateBps'])r[k]=parseDecimal(tr.querySelector(`[data-key="${k}"]`).value);r.carry=tr.querySelector('[data-key="carry"]').checked;}const next=clone(state());next.periods=next.periods.filter(x=>x.id!==p.id);next.periods.push(clone(p));const c=calculate(next).find(x=>x.id===p.id);for(const r of c.rows){const tr=[...document.querySelectorAll('[data-person]')].find(tr=>tr.dataset.person===r.personId);tr.querySelector('[data-result]').textContent=money(r.finalKop);if(r.carry)tr.querySelector('[data-key="accumulatedKop"]').value=number(r.accumulatedKop);}$('#period-totals').innerHTML=`<span>Сумма в периоде<b>${money(c.totals.principalKop)}</b></span><span>На конец периода<b>${money(c.totals.finalKop)}</b></span><span>Проценты за период<b>${signedMoney(c.totals.profitKop)}</b></span>`;$('#form-error').textContent='';}catch(e){error(e);if(throwError)throw e;}}
function personDetail(id){const p=person(id),periods=calculate(state()).filter(x=>x.rows.some(r=>r.personId===id&&(r.accumulatedKop||r.addedKop||r.withdrawnKop||r.finalKop))),summary=portfolioSummary(state(),mode,today(),id);showModal(p.name,`<div class="preview-total"><span>Итого вложено<b>${money(summary.lifetime.investedKop)}</b></span><span>Сумма на конец<b>${money(summary.totals.finalKop)}</b></span><span>Сумма процентов<b>${money(summary.incomeKop)}</b></span></div><p>Режим: <b>${mode==='latest'?'С планами':'Текущие'}</b>. В сводке: ${selectedPeriods(state(),mode).filter(x=>x.rows.some(r=>r.personId===id&&(r.accumulatedKop||r.addedKop||r.withdrawnKop||r.finalKop))).map(x=>`${esc(lot(x.lotId).name)} · ${date(x.startDate)} — ${date(x.endDate)}`).join('; ')||'нет выбранных этапов'}</p><p>Все этапы участника за историю:</p><div class="table-wrap"><table><thead><tr><th>Лот / период</th><th class="numeric">Добавлено</th><th class="numeric">Выведено</th><th class="numeric">Итого</th><th class="numeric">На конец</th></tr></thead><tbody>${periods.map(period=>{const r=period.rows.find(x=>x.personId===id);return `<tr><td><b>${esc(lot(period.lotId).name)}</b><br><small>${shortDate(period.startDate)} — ${date(period.endDate)}</small></td>${['addedKop','withdrawnKop','principalKop','finalKop'].map(k=>`<td class="numeric">${money(r[k])}</td>`).join('')}</tr>`;}).join('')||'<tr><td>Участник ещё не включён в периоды.</td></tr>'}</tbody></table></div>`,button('Закрыть','close')+button('Изменить','edit-person',id,'primary'));}
function periodDetail(id){const p=computed(id);showModal(lot(p.lotId).name+' · '+shortDate(p.startDate)+' — '+date(p.endDate),`${badge(p)}<div class="preview-total"><span>Итого<b>${money(p.totals.principalKop)}</b></span><span>На конец<b>${money(p.totals.finalKop)}</b></span><span>Проценты за период<b>${signedMoney(p.totals.profitKop)}</b></span></div>${periodTable(p)}<p>${esc(p.note||'')}</p>`,button('Отчёт','period-report',id)+button('Изменить','edit-period',id,'primary'));}
function periodText(p){return `${lot(p.lotId).name}\n${date(p.startDate)} — ${date(p.endDate)}\n\n${p.rows.map(r=>`${person(r.personId).name}\nСтавка за период: ${number(r.rateBps)}%\nНакоплено: ${money(r.accumulatedKop)}\nДобавлено: ${money(r.addedKop)}\nВыведено: ${money(r.withdrawnKop)}\nИтого: ${money(r.principalKop)}\nНа конец: ${money(r.finalKop)}\nПроценты за период: ${money(r.profitKop)}`).join('\n\n')}\n\nВСЕ УЧАСТНИКИ\nИтого: ${money(p.totals.principalKop)}\nНа конец: ${money(p.totals.finalKop)}\nПроценты за период: ${money(p.totals.profitKop)}`;}
function report(id){const ps=id?[computed(id)]:selectedPeriods(state(),mode),t=sumPeriods(ps);const text=(id?'':`Сводка на ${date(today())}\n${mode==='latest'?'С учётом планов':'По последним начавшимся периодам'}\nИтого: ${money(t.principalKop)}\nНа конец: ${money(t.finalKop)}\nНачальные суммы: ${money(lifetimeSummary(state(),mode).openingKop)}\nНовые пополнения за историю: ${money(lifetimeSummary(state(),mode).addedKop)}\nИтого вложено: ${money(lifetimeSummary(state(),mode).investedKop)}\nДоход на конец (конечная сумма − Итого вложено): ${money(portfolioSummary(state(),mode).incomeKop)}\n\n`)+ps.map(periodText).join('\n\n────────────\n\n');showModal('Отчёт для копирования',`<textarea id="report-text" class="report-text" readonly aria-label="Текст отчёта">${esc(text)}</textarea><p>Можно скопировать текст или сохранить его в файл.</p>`,button('Скачать .txt','download-report')+button('Копировать','copy-report','','primary'));}
function download(name,content,type){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportBackup(){download('Лоты-резервная-копия-'+today()+'.json',JSON.stringify({backupFormat:'lot-ledger-backup',backupVersion:1,exportedAt:new Date().toISOString(),envelope},null,2),'application/json');localStorage.setItem(BACKUP_KEY,new Date().toISOString());if(view==='data')render();toast('Копия выгружена в JSON');}
async function importFile(file){try{if(file.size>20*1024*1024)throw new Error('Копия должна быть не больше 20 МБ.');const data=JSON.parse(await file.text()),e=validateBackup(data);showModal('Восстановить резервную копию?',`<p>Файл: ${esc(file.name)}</p><div class="import-summary"><span><strong>${e.state.people.length}</strong>участников</span><span><strong>${e.state.lots.length}</strong>лотов</span><span><strong>${e.state.periods.length}</strong>периодов</span><span><strong>${e.history.length}</strong>изменений</span></div><div class="note-strip">Копия заменит текущие данные. Предыдущее состояние сохранится в записи восстановления. Для отдельного хранения скачайте текущую копию.</div><div id="form-error" class="error"></div>`,button('Отмена','close')+'<button id="confirm-import" class="btn primary">Восстановить</button>');$('#confirm-import').onclick=async()=>{if(busy)return;busy=true;try{envelope=await restore(envelope,data);close();render();toast('Копия восстановлена');}catch(e){error(e);}finally{busy=false;}};}catch(e){toast('Не удалось прочитать копию: '+e.message);}}
function stateSummary(s){return `${s.people.length} участников · ${s.lots.length} лотов · ${s.periods.length} периодов`;}
function diffSummary(before,after){const lines=[];for(const key of ['people','lots','periods']){const b=new Map(before[key].map(x=>[x.id,x])),a=new Map(after[key].map(x=>[x.id,x]));for(const [id,x] of a){const old=b.get(id),label=key==='people'?'Участник':key==='lots'?'Лот':'Период';if(!old)lines.push(label+' добавлен: '+(x.name||x.startDate+' — '+x.endDate));else if(JSON.stringify(old)!==JSON.stringify(x)){if(key==='periods'){const bc=calculate(before).find(p=>p.id===id),ac=calculate(after).find(p=>p.id===id);lines.push(label+' '+x.startDate+' — '+x.endDate+': '+money(bc.totals.principalKop)+' → '+money(ac.totals.principalKop)+'; на конец '+money(bc.totals.finalKop)+' → '+money(ac.totals.finalKop));for(const r of x.rows){const oldRow=old.rows.find(o=>o.personId===r.personId);if(JSON.stringify(oldRow)!==JSON.stringify(r)){const name=after.people.find(p=>p.id===r.personId)?.name||'Участник';lines.push(name+': добавлено '+money(oldRow?.addedKop||0)+' → '+money(r.addedKop)+', выведено '+money(oldRow?.withdrawnKop||0)+' → '+money(r.withdrawnKop)+', ставка '+number(oldRow?.rateBps||0)+'% → '+number(r.rateBps)+'%');}}}else lines.push(label+': '+(old.name||'')+' → '+(x.name||'')+(x.archived!==old.archived?(x.archived?' (в архиве)':' (возвращён)'):''));}}for(const [id,x] of b)if(!a.has(id))lines.push('В новом состоянии отсутствует: '+(x.name||x.startDate));}return lines;}
function historyDetail(id){const h=envelope.history.find(h=>h.id===id);showModal(h.label,`<p>${esc(h.details)}</p><p class="help-text">${new Date(h.at).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})} · Москва</p>${h.before&&h.after?`<div class="note-strip"><span>До: ${stateSummary(h.before)}<br>После: ${stateSummary(h.after)}</span></div><div class="report-text">${diffSummary(h.before,h.after).map(x=>`<div>${esc(x)}</div>`).join('')||'Состояние восстановлено из резервной копии.'}</div>`:''}`,button('Закрыть','close')+(h.before?button('Восстановить состояние до изменения','restore-history',h.id):''));}
function restoreHistory(id){const h=envelope.history.find(h=>h.id===id);showModal('Восстановить прежнее состояние?',`<p>Будут восстановлены все данные до изменения «${esc(h.label)}».</p><div class="note-strip">${stateSummary(h.before)}<br>Текущее состояние останется в истории нового восстановления.</div><div class="error" id="form-error"></div>`,button('Отмена','close')+'<button class="btn primary" id="confirm-history">Восстановить</button>');$('#confirm-history').onclick=async()=>{if(await save(clone(h.before),'Восстановлено прежнее состояние','До изменения: '+h.label))close();};}
async function archivePerson(id){const p=person(id);showModal(p.archived?'Вернуть участника?':'Перенести участника в архив?',`<p>${esc(p.name)}</p><p>${p.archived?'Участник снова будет предлагаться в новых периодах.':'Человек останется в старых расчётах. Если у него есть средства, они будут переноситься в следующий период до вывода.'}</p><div class="error" id="form-error"></div>`,button('Отмена','close')+'<button id="confirm-archive" class="btn primary">'+(p.archived?'Вернуть':'В архив')+'</button>');$('#confirm-archive').onclick=async()=>{const next=clone(state());next.people.find(x=>x.id===id).archived=!p.archived;if(await save(next,p.archived?'Участник возвращён из архива':'Участник перенесён в архив',p.name))close();};}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install-btn').hidden=true;}else showModal('Установить «Лоты»',`<p><b>iPhone / iPad:</b> откройте приложение в Safari → «Поделиться» → «На экран Домой».</p><p><b>Mac (Safari):</b> «Файл» → «Добавить в Dock».</p><p><b>Android / компьютер (Chrome, Edge):</b> меню браузера → «Установить приложение» или значок установки в адресной строке.</p><p>Первое открытие требует интернет. После загрузки приложение и сохранённые данные доступны офлайн. Данные отдельной установленной версии Safari могут храниться отдельно: перенесите их через JSON-копию.</p>`,button('Понятно','close'));}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id}=b.dataset;try{switch(a){case'close':close();break;case'new-person':personForm();break;case'edit-person':personForm(id);break;case'archive-person':archivePerson(id);break;case'person-detail':personDetail(id);break;case'new-lot':lotForm();break;case'rename-lot':lotForm(id);break;case'new-period':periodForm();break;case'next-period':periodForm(null,id);break;case'edit-period':periodForm(id);break;case'period-detail':periodDetail(id);break;case'period-report':report(id);break;case'summary-report':report();break;case'metric-detail':metricDetail(id);break;case'mode-current':mode='current';render();break;case'mode-latest':mode='latest';render();break;case'apply-rate':parseDecimal($('#common-rate').value);document.querySelectorAll('[data-key="rateBps"]').forEach(i=>i.value=$('#common-rate').value);updateDraft();break;case'copy-report':try{await navigator.clipboard.writeText($('#report-text').value);toast('Отчёт скопирован');}catch{ $('#report-text').select();toast('Выделено: скопируйте текст');}break;case'download-report':download('Лоты-отчёт-'+today()+'.txt',$('#report-text').value,'text/plain;charset=utf-8');break;case'export':exportBackup();break;case'import':$('#import-file').click();break;case'history-detail':historyDetail(id);break;case'restore-history':restoreHistory(id);break;case'install':install();break;}}catch(e){error(e);}});
document.addEventListener('change',e=>{if(e.target.id==='import-file'&&e.target.files[0])importFile(e.target.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='history-search'){historyQuery=e.target.value;const filtered=envelope.history.filter(h=>(h.label+' '+h.details).toLocaleLowerCase('ru').includes(historyQuery.toLocaleLowerCase('ru'))).slice().reverse();$('#history-items').innerHTML=filtered.map(historyItem).join('')||'<div class="empty">Ничего не найдено.</div>';}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
function connection(){const online=navigator.onLine;$('#connection').classList.toggle('offline',!online);$('#connection').textContent=online?'● Онлайн':'● Офлайн';}
window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
$('#today-label').textContent=new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Moscow'}).format(new Date());
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install-btn').hidden=false;});$('#install-btn').onclick=install;
try{envelope=await openStore();render();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}catch(e){$('#main').innerHTML=`<div class="panel"><h1>Не удалось открыть данные</h1><p>${esc(e.message)}</p><p>Проверьте, что браузер разрешает хранить данные сайта. Откройте приложение в обычной вкладке.</p><button class="btn" id="reload-btn">Попробовать снова</button></div>`;$('#reload-btn').onclick=()=>location.reload();}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(e=>{console.warn('Offline cache:',e);toast('Офлайн-режим пока не готов. Откройте приложение с интернетом ещё раз.');});
